public MainWindow()
		{
			_dbMetaProvider = new DbMetaProvider();
			_generator = new Generator(_dbMetaProvider);


			/*初始化组件*/
			DataContext = this;
			InitializeComponent();


			/*建立樣版選項*/
			TemplateSelectItems = _generator.TemplateTypes
				.Select(t => new OptionItem { Value = t.FullName, Display = formatTemplateName(t), })
				.ToList();
			
		}

